"""Exact source/receipt predicates from the ordinary scheduler; start no jobs."""
from pathlib import Path
import datetime,hashlib,json,zipfile

def build_helpers(kit, runtime_root, transport_root):
    K=Path(kit);E=K/'agent-evidence';B=Path(runtime_root);main=B/'project'
    WORKERS=['primary','independent-probe','helper-probe','auxiliary-probe']
    gate={w:False for w in WORKERS};archive_cache={};object_cache={}
    inventory={r['case']:r for r in json.loads((E/'forward-workload-inventory.json').read_text())['records']}
    namespace=dict(K=K,E=E,B=B,main=main,WORKERS=WORKERS,gate=gate,
                   archive_cache=archive_cache,object_cache=object_cache,
                   inventory=inventory,transport_root=Path(transport_root),
                   Path=Path,hashlib=hashlib,json=json,zipfile=zipfile)
    exec(compile(PURE_PREDICATES,'portable-source-receipt-predicates','exec'),namespace)
    return namespace

PURE_PREDICATES="def logdone(p):\n    if not p.exists():\n        return False\n    with p.open('rb') as f:\n        f.seek(max(0, p.stat().st_size - 1200))\n        s = f.read().decode('utf8', errors='replace')\n    return s.rstrip().endswith('PASS: target declarations have clean transitive axiom audits.')\n\ndef gate_open(w):\n    if gate[w]:\n        return True\n    if w == 'primary':\n        ok = logdone(E / 'resumed-forward-case1156-assembly.log')\n    elif w == 'auxiliary-probe':\n        ok = (E / 'auxiliary-forward-case2133-assembly-task.json').exists()\n    else:\n        p = E / (w + '-case-queue-status.json')\n        try:\n            d = json.loads(p.read_text())\n            ok = len(d['requested']) == len(d['results'])\n        except (OSError, ValueError, KeyError):\n            ok = False\n    gate[w] = ok\n    return ok\n\ndef archive_info(path):\n    st = path.stat()\n    key = (st.st_size, st.st_mtime_ns)\n    if path in archive_cache and archive_cache[path][0] == key:\n        return archive_cache[path][1]\n    with zipfile.ZipFile(path) as z:\n        manifest = json.loads(z.read('source-sync-manifest.json'))\n        keys = {}\n        visiting = set()\n        env = z.read('project/lake-manifest.json') + z.read('project/lean-toolchain')\n\n        def visit(n):\n            if n in keys:\n                return keys[n]\n            assert n not in visiting\n            visiting.add(n)\n            rel = 'project/' + n.replace('.', '/') + '.lean'\n            raw = z.read(rel)\n            assert hashlib.sha256(raw).hexdigest() == manifest[rel]\n            deps = []\n            for l in raw.decode().splitlines():\n                if l.startswith('import '):\n                    for dep in l[7:].split('--')[0].split():\n                        if dep == 'ElevenSquare' or dep.startswith('ElevenSquare.'):\n                            deps.append(visit(dep))\n            keys[n] = hashlib.sha256(raw + ''.join(deps).encode() + env).hexdigest()\n            visiting.remove(n)\n            return keys[n]\n        task = json.loads(z.read(path.name.removeprefix('.t03-runtime-sync-').removesuffix('.zip') + '.json'))\n        for n in task['modules']:\n            visit(n)\n    archive_cache[path] = (key, keys)\n    return keys\n\ndef valid(n, key):\n    receipt = main / 'verification/handoff-cache' / (n + '.json')\n    obj = B / 'lake/build/lib' / Path(*n.split('.')).with_suffix('.olean')\n    try:\n        r = json.loads(receipt.read_text())\n        st = obj.stat()\n        if r.get('source_closure_sha256') != key:\n            return False\n        fingerprint = (st.st_size, st.st_mtime_ns)\n        if obj not in object_cache or object_cache[obj][0] != fingerprint:\n            object_cache[obj] = (fingerprint, hashlib.sha256(obj.read_bytes()).hexdigest())\n        return object_cache[obj][1] == r.get('object_sha256')\n    except (OSError, ValueError):\n        return False\n\ndef externally_reserved():\n    cases = []\n    for w in WORKERS:\n        if gate_open(w):\n            continue\n        if w == 'primary':\n            cases += [1156]\n        elif w == 'auxiliary-probe':\n            cases += [2133]\n        else:\n            defaults = {'independent-probe': [1539, 1530], 'helper-probe': [1312, 1341, 1374, 1450]}\n            cases += defaults[w]\n    reserved = set()\n    for case in cases:\n        p = transport_root / f'.t03-runtime-sync-forward-case{case}-assembly-task.zip'\n        if p.exists():\n            reserved.update((n for n, k in archive_info(p).items() if not valid(n, k)))\n    return reserved\n\ndef completed_cases():\n    out = {1145}\n    for p in E.glob('*-forward-case*-assembly-task.log'):\n        if logdone(p):\n            out.add(int(p.name.split('-forward-case')[1].split('-')[0]))\n    if logdone(E / 'resumed-forward-case1156-assembly.log'):\n        out.add(1156)\n    return out"
